if (!argumentName) return sendTrackedMessage(sock, remoteJid, 'Usage: !qr <text or URL>');
try {
  const text = argumentName.trim();
  const url = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(text)}`;
  await sock.sendMessage(remoteJid, { image: { url }, caption: `📱 QR for: ${text.substring(0, 50)}` });
} catch (e) {
  await sendTrackedMessage(sock, remoteJid, '❌ Failed to generate QR code.');
}
